"""Sample the original cat every five frames, preserving its native pixel grid.

ESR1 shares identical scanlines across frames and run-length encodes palette
indices. Colors are converted only to the screen's RGB565; no quantization.
"""
import base64
from collections import Counter
import hashlib
import json
from pathlib import Path
import struct
from PIL import Image

ROOT = Path(__file__).resolve().parent
SOURCE = ROOT.with_name('task_status_pet') / 'resources'
MOODS = ('idle', 'working', 'thinking', 'approval', 'completed', 'error')
# The source artwork uses 8x8 blocks. Shared bounds preserve pose alignment.
CROP = (64, 56, 680, 592)
WIDTH, HEIGHT = 77, 67
FRAME_MS = 333


def sampled_frames(mood):
    source = Image.open(SOURCE / f'{mood}.webp')
    frames = []
    for i in range(0, source.n_frames, 5):
        source.seek(i)
        frame = source.convert('RGBA')
        left, top, right, bottom = frame.getbbox()
        assert left >= CROP[0] and top >= CROP[1] and right <= CROP[2] and bottom <= CROP[3]
        frames.append(frame.crop(CROP).resize((WIDTH, HEIGHT), Image.Resampling.NEAREST))
    return frames


def color(pixel):
    r, g, b, a = pixel
    return (((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3), a)


def asset(mood):
    rows = [tuple(color(frame.getpixel((x, y))) for x in range(WIDTH))
            for frame in sampled_frames(mood) for y in range(HEIGHT)]
    runs = {}
    counts = Counter()
    for row in dict.fromkeys(rows):
        encoded = []
        at = 0
        while at < WIDTH:
            end = at + 1
            while end < WIDTH and row[end] == row[at] and end - at < 16:
                end += 1
            encoded.append((end - at, row[at]))
            counts[row[at]] += 1
            at = end
        runs[row] = encoded
    # The fifteen most frequent run colors use one byte; others use two.
    palette = {c: i for i, (c, _) in enumerate(counts.most_common())}
    assert len(palette) <= 64
    header = b'ESR1' + bytes((WIDTH, HEIGHT, len(rows) // HEIGHT, len(palette))) + struct.pack('<H', FRAME_MS)
    header += b''.join(struct.pack('<HB', *c) for c in palette)
    offset = len(header) + len(rows) * 2
    offsets, payload = {}, bytearray()
    for row, encoded in runs.items():
        offsets[row] = offset + len(payload)
        for length, c in encoded:
            index = palette[c]
            payload.append(((length - 1) << 4) | min(index, 15))
            if index >= 15:
                payload.append(index)
    return header + b''.join(struct.pack('<H', offsets[row]) for row in rows) + payload


def build():
    packs = []
    for mood in MOODS:
        image = asset(mood)
        data = b'ESP1\x01\x03cat' + struct.pack('<H', len(image)) + image
        assert len(data) <= 8192, (mood, len(data))
        packs.append({'id': f'task-cat-v2-{mood}', 'bytes': len(data),
                      'sha256': hashlib.sha256(data).hexdigest(), 'moods': [mood],
                      'width': WIDTH, 'height': HEIGHT, 'frames': image[6], 'frameMs': FRAME_MS,
                      'chunks': [{'offset': offset, 'data': base64.b64encode(data[offset:offset+256]).decode()}
                                 for offset in range(0, len(data), 256)]})
        (ROOT / 'resources' / f'cat-{mood}.esp').write_bytes(data)
    # Remove only superseded files produced by the previous generator.
    for name in ('cat-0.esp', 'cat-1.esp'):
        (ROOT / 'resources' / name).unlink(missing_ok=True)
    (ROOT / 'src/assets.ts').write_text('// Generated by generate_assets.py from task_status_pet/resources.\nexport const PACKS = '
                                      + json.dumps(packs, indent=2) + ' as const;\n', encoding='utf-8')
    print('Scene packs:', [(p['id'], p['bytes'], p['frames']) for p in packs])


if __name__ == '__main__':
    build()
